import pandas as pd
df = execute_sql_query("""
    SELECT 
        "[Employee Master[Sector]]" AS sector,
        rec['Employee Assignment History[Assignment Experience (Years & Months)]'] AS experience_str
    FROM enterprise_data,
    UNNEST("[Employee Assignment History[Assignment Name][Position Title][Employee Grade][Assignment Start Date][Assignment End Date][Assignment Experience (Years & Months)]]") AS t(rec)
    WHERE "[Employee Master[Sector]]" != '' AND "[Employee Master[Sector]]" IS NOT NULL
    AND rec['Employee Assignment History[Assignment Experience (Years & Months)]'] IS NOT NULL
    AND rec['Employee Assignment History[Assignment Experience (Years & Months)]'] != ''
""")
sector_experience = {}
for idx, row in df.iterrows():
    sector = row['sector']
    exp_str = row['experience_str']
    if sector not in sector_experience:
        sector_experience[sector] = []
    if pd.notna(exp_str):
        try:
            exp_val = float(str(exp_str).strip().replace(',', ''))
            sector_experience[sector].append(exp_val)
        except (ValueError, TypeError):
            pass
results = []
for sector, experiences in sector_experience.items():
    if len(experiences) > 0:
        avg_experience = sum(experiences) / len(experiences)
        results.append(f'{sector}: {round(avg_experience, 2)} years average')
    else:
        results.append(f'{sector}: No data')
if len(results) > 0:
    result = {'type': 'string', 'value': f'Average ADEO experience by sector:\n' + '\n'.join(results)}
else:
    result = {'type': 'string', 'value': 'No sector experience data found in the database.'}
